sys_variable_value.value:
(function execute(inputs, outputs) {
    var bldg = inputs.lab_1009;
    var bParser = bldg;
    //var bParser = JSON.parse(bldg);
    var arrBldg = [];
    var arrHQ = [];
    var arrDeath = [];
    var arrOther = [];
    var arrEmp = [];
    var arrOffice = [];
    var arrHours = [];
    var arrComment = [];
    var arrDisable = [];
    var arrMinor = [];
    var arrAddr = [];
    var arrBldgNames = [];


    for (var b = 0; b < bParser.length; b++) { //loop through ALL of the buildings

        //get variables from LAB1058 data collector
        var repData = new GlideRecord('x_hccc_hoc_ohs_lab1058_staging_table');
        repData.addQuery('report_year', inputs.ohsm_repo_year);
        repData.addQuery('building', bParser[b].building);
        repData.query();
        repData.next();
        var disabling = repData.disabling_injury.split(',');
        var minor = repData.minor_injury.split(',');

        //set Address from building (location record)
        var loc = new GlideRecord('cmn_location');
        loc.get('sys_id', bParser[b].building);
        var address = loc.street + '\n' + loc.city + ' ' + loc.state + ' ' + loc.zip;

        //create arrays of values for JSON 
        arrBldg.push(bParser[b].building);
        if (bParser[b].headquarters == 'true') //convert T/F to Y/N for form data requirement
            arrHQ.push('Y');
        else
            arrHQ.push('N');
        arrDeath.push(bParser[b].number_of_deaths);
        arrOther.push(bParser[b].number_of_other_hazardous_occurrences);
        arrEmp.push(bParser[b].total_number_of_employees);
        arrOffice.push(bParser[b].number_of_office_employees);
        arrHours.push(bParser[b].total_number_of_hours_worked);
        arrComment.push(bParser[b].comments);
        arrDisable.push(disabling[12]);
        arrMinor.push(minor[12]);
        arrAddr.push(address);
        arrBldgNames.push(loc.name);

        //arrays are built.
    }

    var bldgJson = {
        year: inputs.ohsm_repo_year.toString(),
        building: arrBldg.toString(),
        hq: arrHQ.toString(),
        deaths: arrDeath.toString(),
        other: arrOther.toString(),
        emp: arrEmp.toString(),
        office: arrOffice.toString(),
        hours: arrHours.join('^'),
        comment: arrComment.toString(),
        disable: arrDisable.toString(),
        minorInj: arrMinor.toString(),
        addr: arrAddr.toString(),
        bldgName: arrBldgNames.toString()
    }; //populate JSON object with array data.

    outputs.subject_person = inputs.ohsm_repo_contact_person;
    outputs.json_draft = JSON.stringify(bldgJson); //return our data.
    
})(inputs, outputs);

